def fib(n: int):
    """Return n-th Fibonacci number.
    >>> fib(10)
    55
    >>> fib(1)
    1
    >>> fib(8)
    21
    """
    if not isinstance(n, int):
        raise TypeError("n must be an integer")
    if n < 0:
        raise ValueError("n must be non-negative")

    def _fd(k: int):
        # returns (F_k, F_{k+1})
        if k == 0:
            return (0, 1)
        a, b = _fd(k >> 1)
        c = a * ((b << 1) - a)  # F_{2m} = F_m * (2*F_{m+1} - F_m)
        d = a * a + b * b      # F_{2m+1} = F_m^2 + F_{m+1}^2
        if k & 1:
            return (d, c + d)
        else:
            return (c, d)

    return _fd(n)[0]

